final nativeContext = _initNativeContext();
final channel = NativeMethodChannel('my_method_channel', context: nativeContext);

channel.setMessageHandler((call) async {
  if (call.method == 'myMethod') {
    return 'myResult';
  }
  return null;
});

final res = await channel.invokeMethod('someMethod', 'someArg');
